<?php

namespace App\Http\Controllers;

use App\Models\PurchaseOrder;
use App\Services\ExcelReportService;
use Barryvdh\DomPDF\Facade\Pdf;
use Barryvdh\DomPDF\ServiceProvider;
use Carbon\Carbon;
use Illuminate\Http\Request;
use Illuminate\Http\Response;
use Illuminate\Support\Facades\Auth;
use Symfony\Component\HttpFoundation\StreamedResponse;

class PurchaseOrderPrintController extends Controller
{
    /**
     * Download / Stream Single Official Purchase Order (Vendor Copy).
     */
    public function downloadSingle(PurchaseOrder $purchaseOrder): Response
    {
        $this->authorizeAccess();

        $purchaseOrder->load(['supplier', 'material']);

        $logoBase64 = $this->getLogoBase64();

        $this->ensureDompdfRegistered();

        $safePoNumber = str_replace(['/', '\\'], '-', $purchaseOrder->po_number);
        $filename = "PO_{$safePoNumber}.pdf";

        $data = [
            'po' => $purchaseOrder,
            'logo' => $logoBase64,
            'printedBy' => Auth::user()?->name ?? 'Kasir Logistik',
            'printedAt' => Carbon::now()->translatedFormat('d F Y H:i'),
        ];

        try {
            $pdf = Pdf::loadView('pdf.purchase-order-single', $data)->setPaper('a4', 'portrait');

            return $pdf->stream($filename);
        } catch (\Throwable $e) {
            return response()->view('pdf.purchase-order-single', array_merge($data, ['isHtmlFallback' => true]));
        }
    }

    /**
     * Download / Stream Purchase Order Management & Audit Report (Internal Report).
     */
    public function downloadReport(Request $request): Response
    {
        $this->authorizeAccess();

        $year = (int) $request->input('year', Carbon::now()->year);
        $month = (int) $request->input('month', Carbon::now()->month);
        $status = $request->input('status');
        $supplierId = $request->input('supplier_id');

        $query = PurchaseOrder::with(['supplier', 'material'])
            ->whereYear('po_date', $year)
            ->whereMonth('po_date', $month);

        if ($status) {
            $query->where('status', $status);
        }

        if ($supplierId) {
            $query->where('supplier_id', $supplierId);
        }

        $purchaseOrders = $query->orderBy('po_date', 'asc')->orderBy('id', 'asc')->get();

        // Calculate summary aggregates
        $totalOrders = $purchaseOrders->count();
        $totalGrandAmount = $purchaseOrders->sum('grand_total');
        $materialSummary = $purchaseOrders->groupBy('material_type_input')
            ->map(fn ($group) => [
                'count' => $group->count(),
                'qty' => $group->sum('qty_ordered'),
                'unit' => $group->first()->unit ?? 'Satuan',
            ]);

        $statusSummary = [
            'draft' => $purchaseOrders->where('status', 'draft')->count(),
            'disetujui' => $purchaseOrders->where('status', 'disetujui')->count(),
            'muat_kapal' => $purchaseOrders->where('status', 'muat_kapal')->count(),
            'pelayaran' => $purchaseOrders->where('status', 'pelayaran')->count(),
            'bongkar' => $purchaseOrders->where('status', 'bongkar')->count(),
            'selesai' => $purchaseOrders->where('status', 'selesai')->count(),
        ];

        $logoBase64 = $this->getLogoBase64();

        $monthName = Carbon::createFromDate($year, $month, 1)->translatedFormat('F Y');
        $filename = "Rekap_PO_TBI_{$year}_{$month}.pdf";

        $data = [
            'purchaseOrders' => $purchaseOrders,
            'year' => $year,
            'month' => $month,
            'monthName' => $monthName,
            'totalOrders' => $totalOrders,
            'totalGrandAmount' => $totalGrandAmount,
            'materialSummary' => $materialSummary,
            'statusSummary' => $statusSummary,
            'logo' => $logoBase64,
            'printedBy' => Auth::user()?->name ?? 'Kasir Logistik',
            'printedAt' => Carbon::now()->translatedFormat('d F Y H:i'),
        ];

        $this->ensureDompdfRegistered();

        try {
            $pdf = Pdf::loadView('pdf.purchase-order-report', $data)->setPaper('a4', 'landscape');

            return $pdf->stream($filename);
        } catch (\Throwable $e) {
            return response()->view('pdf.purchase-order-report', array_merge($data, ['isHtmlFallback' => true]));
        }
    }

    /**
     * Download Purchase Order Management & Audit Report in formatted Excel (.xlsx) with embedded TBI logo.
     */
    public function downloadReportExcel(Request $request, ExcelReportService $excelService): StreamedResponse
    {
        $this->authorizeAccess();

        $year = (int) $request->input('year', Carbon::now()->year);
        $month = (int) $request->input('month', Carbon::now()->month);
        $status = $request->input('status');
        $supplierId = $request->input('supplier_id');

        $query = PurchaseOrder::with(['supplier', 'material'])
            ->whereYear('po_date', $year)
            ->whereMonth('po_date', $month);

        if ($status) {
            $query->where('status', $status);
        }

        if ($supplierId) {
            $query->where('supplier_id', $supplierId);
        }

        $purchaseOrders = $query->orderBy('po_date', 'asc')->orderBy('id', 'asc')->get();

        return $excelService->exportPurchaseOrderReport(
            purchaseOrders: $purchaseOrders,
            year: $year,
            month: $month,
            printedBy: Auth::user()?->name ?? 'Kasir Logistik'
        );
    }

    /**
     * Enforce RBAC access authorization.
     */
    protected function authorizeAccess(): void
    {
        if (! Auth::check()) {
            abort(401, 'Silakan masuk terlebih dahulu.');
        }

        $user = Auth::user();
        if (! in_array($user->role, ['admin', 'kasir_logistik', 'demo'], true)) {
            abort(403, 'Akses Ditolak: Anda tidak memiliki izin untuk mengunduh dokumen Purchase Order.');
        }
    }

    /**
     * Ensure Dompdf service provider is bound dynamically if package auto-discovery is delayed or missing on shared hosting.
     */
    protected function ensureDompdfRegistered(): void
    {
        if (! app()->bound('dompdf.wrapper') && class_exists(ServiceProvider::class)) {
            app()->register(ServiceProvider::class);
        }
    }

    /**
     * Embedded fallback Base64 logo to guarantee logo appears on any shared hosting.
     */
    private const EMBEDDED_LOGO_BASE64 = '';

    /**
     * Resolve Base64 Data URI for DOMPDF and HTML views.
     */
    protected function getLogoBase64(): string
    {
        $candidates = [
            public_path('images/logo.png'),
            public_path('logo.png'),
            resource_path('images/logo.png'),
            base_path('public/images/logo.png'),
            base_path('public/logo.png'),
            base_path('htdocs/images/logo.png'),
            base_path('htdocs/logo.png'),
            isset($_SERVER['DOCUMENT_ROOT']) ? $_SERVER['DOCUMENT_ROOT'].'/images/logo.png' : null,
            isset($_SERVER['DOCUMENT_ROOT']) ? $_SERVER['DOCUMENT_ROOT'].'/logo.png' : null,
        ];

        foreach ($candidates as $cand) {
            if ($cand && file_exists($cand) && is_readable($cand)) {
                $content = (string) file_get_contents($cand);
                if (! empty($content)) {
                    return 'data:image/png;base64,'.base64_encode($content);
                }
            }
        }

        return 'data:image/png;base64,'.self::EMBEDDED_LOGO_BASE64;
    }
}
